const groqRaw = $('🤖 Groq: Community AI').item.json;
const texto = groqRaw.choices?.[0]?.message?.content || '';

// Parse structured output
const get = (label) => {
  const regex = new RegExp(`${label}[:\s]+([^\n]+)`, 'i');
  const match = texto.match(regex);
  return (match?.[1] || '').trim();
};

const intencion = get('INTENCI[OÓ]N');
const respuesta = get('RESPUESTA');
const lead = get('LEAD');
const pregunta = get('PREGUNTA');
const siguientePaso = get('SIGUIENTE PASO');

// Build the public reply: response + qualification question
const wa_link = $('🔧 Preparar Contexto Community AI').item.json.wa_link;
let respuestaPublica = respuesta;
if (pregunta) respuestaPublica += ' ' + pregunta;

// Add CTA if transactional or commercial
if (['transaccional', 'comercial'].includes(intencion.toLowerCase()) || lead === 'caliente') {
  if (siguientePaso === 'whatsapp') {
    respuestaPublica += ` Escríbenos por WhatsApp para una cotización rápida: ${wa_link}`;
  } else if (siguientePaso === 'dm') {
    respuestaPublica += ' Escríbenos por DM y te ayudamos enseguida.';
  }
}

const evento = $('🔍 Extraer Evento FB/IG').item.json;

return [{ json: {
  intencion,
  respuesta,
  respuestaPublica,
  lead,
  pregunta,
  siguientePaso,
  plataforma: evento.plataforma,
  tipo: evento.tipo,
  comentarioId: evento.comentarioId,
  postId: evento.postId,
  mediaId: evento.mediaId,
  usuarioId: evento.usuarioId,
  usuarioNombre: evento.usuarioNombre,
  texto_completo_groq: texto
}}];

